 "content": "def transform(grid):
    """Recolor uniform solid blocks of at least 5x5 to 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = set()
    # Every qualifying cell belongs to some contiguous 5x5 monochrome window.
    for r in range(h - 4):
        for c in range(w - 4):
            color = grid[r][c]
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 5)
                   for cc in range(c, c + 5)):
                # Extend the qualifying rectangle in all directions while the
                # same color continues; this handles blocks larger than 5x5.
                top, left, bottom, right = r, c, r + 5, c + 5
                changed = True
                while changed:
                    changed = False
                    if top > 0 and all(grid[top - 1][x] == color for x in range(left, right)):
                        top -= 1; changed = True
                    if bottom < h and all(grid[bottom][x] == color for x in range(left, right)):
                        bottom += 1; changed = True
                    if left > 0 and all(grid[y][left - 1] == color for y in range(top, bottom)):
                        left -= 1; changed = True
                    if right < w and all(grid[y][right] == color for y in range(top, bottom)):
                        right += 1; changed = True
                marked.update((y, x) for y in range(top, bottom) for x in range(left, right))
    for r, c in marked:
        out[r][c] = 4
    return out

