 "content": "def transform(grid):
    """Replace large, exactly rectangular monochrome components with 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if len(comp) < 25:
                continue
            top = min(y for y, x in comp); bottom = max(y for y, x in comp)
            left = min(x for y, x in comp); right = max(x for y, x in comp)
            area = (bottom-top+1)*(right-left+1)
            if area == len(comp) and bottom-top+1 >= 5 and right-left+1 >= 5:
                for y, x in comp:
                    out[y][x] = 4
    return out

