 "content": "def transform(grid):
    """Recolor solid monochrome patches at least 5 by 5 to color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    windows = {}
    # Record every uniform 5x5 window, grouped by its color.
    for r in range(h - 4):
        for c in range(w - 4):
            color = grid[r][c]
            if all(grid[y][x] == color
                   for y in range(r, r + 5)
                   for x in range(c, c + 5)):
                windows.setdefault(color, set()).add((r, c))
    # Overlapping windows tile each large uniform patch. Their union is the
    # patch, without guessing extensions into adjacent regions.
    for starts in windows.values():
        for r, c in starts:
            for y in range(r, r + 5):
                for x in range(c, c + 5):
                    out[y][x] = 4
    return out

