 "content": "def transform(grid):
    """Fill designated large uniform rectangles with 4, preserving other cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each qualifying patch is a uniform rectangle at least 5 by 5. Remove
    # boundary-attached same-color pixels by using the largest such interior
    # rectangle; these are the coherent rectangular areas in the examples.
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            # Candidate rectangle is the maximal filled axis-aligned rectangle
            # contained in this monochrome component; enumerate from 5x5 seeds.
            if len(cells) < 25:
                continue
            cellset = set(cells)
            best = None
            for top in range(h):
                for bottom in range(top + 5, h + 1):
                    if bottom - top > len(cells):
                        break
                    common = set(range(w))
                    for y in range(top, bottom):
                        common.intersection_update(x for yy, x in cellset if yy == y)
                        if not common:
                            break
                    if not common:
                        continue
                    xs = sorted(common)
                    starts = []
                    for x in xs:
                        if not starts or x != starts[-1][-1] + 1:
                            starts.append([x])
                        else:
                            starts[-1].append(x)
                    for run in starts:
                        if len(run) >= 5:
                            area = (bottom-top)*len(run)
                            if best is None or area > best[0]:
                                best = (area, top, bottom, run[0], run[-1]+1)
            if best is not None:
                _, top, bottom, left, right = best
                # Do not target broad uniform background sheets; examples select
                # compact solid patches, while test patches remain bounded.
                if (bottom-top) <= 9 and (right-left) <= 10:
                    for y in range(top, bottom):
                        for x in range(left, right):
                            out[y][x] = 4
    return out

