 "content": "def transform(grid):
    """Recolor rectangular uniform patches of size at least 5x5 to color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A valid patch may have same-colored noise adjacent to its boundary.
    # Enumerate uniform rectangles and choose largest area for each seed color
    # component, deduplicating overlapping proposals.
    proposals = set()
    for top in range(h):
        for bottom in range(top + 5, h + 1):
            for left in range(w):
                color = grid[top][left]
                right = left
                while right < w and all(grid[r][right] == color for r in range(top, bottom)):
                    right += 1
                    if right - left >= 5:
                        proposals.add((color, top, bottom, left, right))
    # Retain inclusion-maximal rectangles; smaller seed fragments of the same
    # patch are redundant. A cell is recolored when it belongs to such a patch.
    maximal = []
    for rect in proposals:
        color, t, b, l, r = rect
        if any(color == cc and t2 <= t and b2 >= b and l2 <= l and r2 >= r
               and (t2, b2, l2, r2) != (t, b, l, r)
               for cc, t2, b2, l2, r2 in proposals):
            continue
        maximal.append(rect)
    for color, t, b, l, r in maximal:
        if b - t >= 5 and r - l >= 5:
            for y in range(t, b):
                for x in range(l, r):
                    out[y][x] = 4
    return out

