 "content": "def transform(grid):
    """Replace each embedded solid rectangle at least 5x5 with color 4.

    The qualifying regions are the interiors of large same-color blocks, even
    if unrelated same-color pixels touch their perimeter. Find candidate
    monochrome rectangles and mark cells from maximal such rectangles.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = set()
    # For each vertical interval, find horizontal runs whose every cell matches
    # the seed color. This includes blocks with adjacent same-colored noise.
    for top in range(h - 4):
        for bottom in range(top + 5, h + 1):
            for left in range(w - 4):
                color = grid[top][left]
                right = left
                while right < w and all(grid[r][right] == color for r in range(top, bottom)):
                    right += 1
                if right - left < 5:
                    continue
                # Grow leftward to the maximal uniform span for this height.
                while left > 0 and all(grid[r][left - 1] == color for r in range(top, bottom)):
                    left -= 1
                # Check that this rectangle cannot be extended vertically.
                can_up = top > 0 and all(grid[top - 1][x] == color for x in range(left, right))
                can_down = bottom < h and all(grid[bottom][x] == color for x in range(left, right))
                if can_up or can_down:
                    continue
                for r in range(top, bottom):
                    for c in range(left, right):
                        marked.add((r, c))
    for r, c in marked:
        out[r][c] = 4
    return out

