    candidates = set()
    for top in range(h - 4):
        for bottom in range(top + 5, h + 1):
            height = bottom - top
            for left in range(w - 4):
                color = grid[top][left]
                right = left
                while right < w and all(grid[r][right] == color for r in range(top, bottom)):
                    right += 1
                # The maximal uniform span at this top/height is a rectangle candidate.
                if right - left >= 5 and height * (right - left) <= 45:
                    # Require maximal vertical extent for the chosen span.
                    if top > 0 and all(grid[top-1][x] == color for x in range(left,right)):
                        continue
                    if bottom < h and all(grid[bottom][x] == color for x in range(left,right)):
                        continue
                    candidates.add((top,bottom,left,right,color))
    # Keep only the largest area candidates within each connected monochrome
    # region; prevents recoloring incidental smaller rectangles in noisy fields.
