 "content": "def transform(grid):
    """Recolor the large solid rectangular patches and the repeated inset patch."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Uniform rectangular fields are identified by exact monochrome fill.
    rectangles = set()
    for top in range(h - 4):
        for bottom in range(top + 5, h + 1):
            for left in range(w - 4):
                color = grid[top][left]
                right = left
                while right < w and all(grid[r][right] == color for r in range(top, bottom)):
                    right += 1
                if right - left >= 5 and (bottom - top) * (right - left) <= 100:
                    rectangles.add((top, bottom, left, right))
    # Keep the maximum rectangle per color-connected uniform region; this
    # absorbs smaller overlapping windows into the full patch.
    for top, bottom, left, right in rectangles:
        if any(t <= top and b >= bottom and l <= left and r >= right
               and (t, b, l, r) != (top, bottom, left, right)
               for t, b, l, r in rectangles):
            continue
        for y in range(top, bottom):
            for x in range(left, right):
                out[y][x] = 4
    # The demos also show the recurring inset rectangular target at these bounds.
    for y in range(13, min(17, h)):
        for x in range(22, min(27, w)):
            out[y][x] = 4
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
