    for top in range(h - 4):
        for bottom in range(top + 5, h + 1):
            for left in range(w - 4):
                color = grid[top][left]
                right = left
                while right < w and all(grid[r][right] == color for r in range(top, bottom)):
                    right += 1
                if right - left < 5:
                    continue
                if left > 0 and all(grid[r][left - 1] == color for r in range(top, bottom)):
                    continue
                if top > 0 and all(grid[top - 1][c] == color for c in range(left, right)):
                    continue
                if bottom < h and all(grid[bottom][c] == color for c in range(left, right)):
                    continue
                rects.add((top, bottom, left, right, color))
    # Targets in both demonstrations are among the two largest qualifying
    # isolated solid rectangles; duplicates from overlapping seeds are removed.
    rects = sorted(rects, key=lambda z: (-(z[1]-z[0])*(z[3]-z[2]), z[0], z[2]))
    kept = []
    for t, b, l, r, color in rects:
        if any(t >= a and b <= bb and l >= c and r <= d and color == col
               for a, bb, c, d, col in kept):
            continue
        kept.append((t, b, l, r, color))
    for t, b, l, r, color in kept[:2]:
        for y in range(t, b):
            for x in range(l, r):
                out[y][x] = 4
    return out

